import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BxGh02fV.js";const d=JSON.parse('{"title":"First launch","description":"","frontmatter":{"title":"First launch"},"headers":[],"relativePath":"en/guide/first-run.md","filePath":"en/guide/first-run.md"}'),s={name:"en/guide/first-run.md"};function n(i,e,l,h,u,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="first-launch" tabindex="-1">First launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First launch&quot;">​</a></h1><p>On the very first launch, Effortless does not know who you are yet. Before showing you the workspace picker, it takes you through a short assistant: your profile, deploying Effortless into your AI tools, then your first workspace.</p><h2 id="the-startup-screen" tabindex="-1">The startup screen <a class="header-anchor" href="#the-startup-screen" aria-label="Permalink to &quot;The startup screen&quot;">​</a></h2><p>At every launch, the mascot shows for a moment while the app loads your profile, then fades out. Then:</p><ul><li>if you already have a profile, you land on the picker (<a href="/Effortless/en/guide/start.html">Open a workspace</a>);</li><li>otherwise, the first-launch assistant opens.</li></ul><h2 id="the-first-launch-assistant" tabindex="-1">The first-launch assistant <a class="header-anchor" href="#the-first-launch-assistant" aria-label="Permalink to &quot;The first-launch assistant&quot;">​</a></h2><p>At the top, four numbered dots show where you are. At the bottom, <strong>Back</strong> returns to the previous step; <strong>Next</strong> moves on; <strong>Later</strong> skips an optional step.</p><h3 id="_1-welcome" tabindex="-1">1. Welcome <a class="header-anchor" href="#_1-welcome" aria-label="Permalink to &quot;1. Welcome&quot;">​</a></h3><p>&quot;Welcome to Effortless&quot; introduces the app and reminds you that everything stays on your machine (<code>~/.effortless</code>). Click <strong>Get started</strong>.</p><h3 id="_2-create-your-profile" tabindex="-1">2. Create your profile <a class="header-anchor" href="#_2-create-your-profile" aria-label="Permalink to &quot;2. Create your profile&quot;">​</a></h3><p>A local identity, no account. It signs your decisions, your specs and your commits.</p><ul><li><strong>Name</strong>: required.</li><li><strong>Email</strong>: required here, in the <code>name@domain.dev</code> format.</li><li><strong>Default author</strong>: required, &quot;the signature of your work&quot;.</li></ul><p>The <strong>Your signature</strong> box previews how your name will appear, for instance on a decision. This step cannot be skipped: <strong>Next</strong> stays greyed out until the name, email and author are valid, and it is the button that saves the profile.</p><h3 id="_3-deploy-effortless-into-your-tools" tabindex="-1">3. Deploy Effortless into your tools <a class="header-anchor" href="#_3-deploy-effortless-into-your-tools" aria-label="Permalink to &quot;3. Deploy Effortless into your tools&quot;">​</a></h3><p>This step installs the Effortless MCP server and its skills into the AI assistants detected on your machine (Claude Code, opencode…). It is the same panel as <strong>Preferences</strong> › <strong>MCP &amp; Skills</strong>: select the assistants, then <strong>Deploy</strong>. See <a href="/Effortless/en/guide/preferences.html">Profile and preferences</a>.</p><p>If an older installation is detected, a &quot;Legacy installation detected&quot; banner offers to migrate it.</p><p>You can skip this step with <strong>Later</strong> and deploy from the preferences whenever you like.</p><h3 id="_4-your-first-workspace" tabindex="-1">4. Your first workspace <a class="header-anchor" href="#_4-your-first-workspace" aria-label="Permalink to &quot;4. Your first workspace&quot;">​</a></h3><p>A workspace is an Effortless project.</p><ul><li><strong>Open a folder…</strong>: pick a folder that already holds an Effortless project;</li><li><strong>Create a workspace…</strong>: pick a folder, Effortless initializes it.</li></ul><p>Either way, the workspace opens in a tab and the assistant closes. <strong>Finish</strong> (or <strong>Later</strong>) closes the assistant without opening anything: you then land on the picker.</p><h2 id="replay-the-introduction" tabindex="-1">Replay the introduction <a class="header-anchor" href="#replay-the-introduction" aria-label="Permalink to &quot;Replay the introduction&quot;">​</a></h2><p><strong>Preferences</strong> › <strong>Getting started</strong> › <strong>Replay the introduction</strong> replays the assistant. Your profile already exists: the identity step is then prefilled.</p><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>An agent has no first-launch assistant. <code>effortless_deploy</code> does the job of step 3, and <code>effortless_init</code> creates a workspace.</p>',25)])])}const f=t(s,[["render",n]]);export{d as __pageData,f as default};
